//     $(this).attr('href','http://bshare.optimix.cn/barCode?site=weixin&url='+encodeURIComponent(document.location.href)+'&title='+encodeURIComponent(document.title));
// })
$('.cd_wx').click(function(){
$(this).attr('href','https://api.qrserver.com/v1/create-qr-code/?size=150x150&data='+encodeURIComponent(document.location.href)+'&title='+encodeURIComponent(document.title));
})
$('.cd_wb').click(function(){
$(this).attr('href','http://service.weibo.com/share/share.php?appkey=&title='+encodeURIComponent(document.title)+'&url='+encodeURIComponent(document.location.href)+'&searchPic=false&style=simple');
})

