$("返回顶部
").appendTo('body');
$("#toTop").css({
// width: '50px',
// height: '50px',
bottom: '10px',
right: '15px',
position: 'fixed',
cursor: 'pointer',
zIndex: '2',
});
if ($(this).scrollTop() == 0) {
$("#toTop").hide();
}
$(window).scroll(function (event) {
/* Act on the event */
if ($(this).scrollTop() == 0) {
$("#toTop").hide();
}
if ($(this).scrollTop() != 0) {
$("#toTop").show();
}
});
$("#toTop").click(function (event) {
/* Act on the event */
$("html,body").animate({
scrollTop: "0px"
},
300
)
});
}
});
$('.close-btn').click(function() {
$('.search-mode').hide()
})
function opSearch(params) {
$('.search-mode').show()
}
$(document).ready(function () {
$('.fy1 a').each(function(){
if($(this).text()=='上页' || $(this).text()=='下页'){
$(this).addClass('cd_sx');
}
})
});
$('.cd_qq').click(function(){
$(this).attr('href','https://sns.qzone.qq.com/cgi-bin/qzshare/cgi_qzshare_onekey?url='+encodeURIComponent(document.location.href)+'&title='+encodeURIComponent(document.title));
})
